const std::string &IdHandler::SelectIdInfo(const std::string &macAddress, const std::string &deviceNetId)
{
    static const std::string defaultInfo = HDI_ID_INFO_DEFAULT;
    if (!macAddress.empty()) {
        return macAddress;
    }
    return !deviceNetId.empty() ? deviceNetId : defaultInfo;
}

int32_t HpaeRendererManager::CreateInputSession(const HpaeStreamInfo &streamInfo)
{
    HpaeNodeInfo nodeInfo;
    ConfigNodeInfo(nodeInfo, streamInfo);
    nodeInfo.sceneType = TransToProperSceneType(streamInfo.effectInfo.streamUsage, streamInfo.effectInfo.effectScene);
    TransNodeInfoForCollaboration(nodeInfo, isCollaborationEnabled_);
    nodeInfo.statusCallback = weak_from_this();
    nodeInfo.deviceClass = sinkInfo_.deviceClass;
    nodeInfo.deviceNetId = sinkInfo_.deviceNetId;
    // Remote sink routing ignores mac; keep volume-side info selection consistent with sink creation
    nodeInfo.macAddress = IsRemoteDevice() ? "" : sinkInfo_.macAddress;

